import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { useParams } from 'react-router-dom';
import Header from '../Components/'; // Importing the Header component
import Footer from './Footer'; // Importing the Footer component

// Defining constants for the API key and base URL
const apiKey = '499d99db6ce23991d21afde0deede0f1';
const baseUrl = 'https://api.themoviedb.org/3';

function MoviePage() {
  // Using the useParams hook to get the ID of the selected movie from the URL parameter
  const { id } = useParams();

  // Setting up state for the movie details, cast, and reviews
  const [movieDetails, setMovieDetails] = useState(null);
  const [cast, setCast] = useState([]);
  const [reviews, setReviews] = useState([]);

  // Using an effect hook to fetch data from the API when the component mounts
  useEffect(() => {
    const fetchData = async () => {
      // Fetching the details for the selected movie from the TMDb API
      const detailsResponse = await axios.get(
        `${baseUrl}/movie/${id}`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      setMovieDetails(detailsResponse.data);

      // Fetching the credits for the selected movie from the TMDb API
      const creditsResponse = await axios.get(
        `${baseUrl}/movie/${id}/credits`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      setCast(creditsResponse.data.cast);

      // Fetching the reviews for the selected movie from the TMDb API
      const reviewsResponse = await axios.get(
        `${baseUrl}/movie/${id}/reviews`,
        {
          params: {
            api_key: apiKey,
          },
        }
      );
      setReviews(reviewsResponse.data.results);
    };
    fetchData();
  }, [id]);

  // Rendering the Header, movie details, cast, reviews, and Footer
  return (
    <>
      <Header />
      <div>
        {movieDetails && (
          <>
            <h1>{movieDetails.title}</h1>
            <p>{movieDetails.overview}</p>
            <h2>Cast</h2>
            <ul>
              {cast.map((actor) => (
                <li key={actor.id}>
                  <img
                    src={`https://image.tmdb.org/t/p/w500${actor.profile_path}`}
                    alt={actor.name}
                    style={{ height: '100px' }}
                  />
                  {actor.name}
                </li>
              ))}
            </ul>
            <h2>Reviews</h2>
            <ul>
              {reviews.map((review) => (
                <li key={review.id}>{review.content}</li>
              ))}
            </ul>
          </>
        )}
      </div>
      <Footer />
    </>
  );
}

export default MoviePage;

